@export var display_name: String = "SIGNAL CIRCUIT"
@export var hint_text: String = "Activate all three nodes in the correct order."
@export var win_text: String = "CIRCUIT COMPLETE!"
@export var wrong_text: String = "Wrong order - circuit reset."
@export var node_names: Array[String] = []
@export var node_colors: Array[Color] = []
@export var sequence: Array[int] = []

func sequence_size() -> int:
    return sequence.size()

func display_order() -> String:
    var parts: Array[String] = []
    for idx in sequence:
        if idx >= 0 and idx < node_names.size():
            parts.append(node_names[idx])
    return " -> ".join(parts)
`;

