{"code": "const mainScript = `extends Control
## Signal Circuit - sequence memory game.
## Three focusable node buttons must be activated in the order stored in
## a SignalSequence resource. Wrong order resets; completion wins.
## Works with mouse, keyboard and gamepad focus.

const SEQUENCE_PATH := "res://validation_games/signal_circuit/circuit_sequence.tres"
const WRONG_RESET_DELAY := 0.7
const UNLOCK_LEVELS := 5

@onready var bg: ColorRect = %Background
@onready var title: Label = %TitleLabel
@onready var hint: Label = %HintLabel
@onready var status: Label = %StatusLabel
@onready var win_panel: PanelContainer = %WinPanel
@onready var nodes_box: HBoxContainer = %NodesBox
@onready var restart_button: Button = %RestartButton
@onready var sfx_player: AudioStreamPlayer = %SfxPlayer
@onready var wrong_timer: Timer = %WrongTimer

var _sequence: SignalSequence
var _progress := 0
var _busy := false
var _completed := false
var _volume := 0.0
var _unlocked := false

func _ready() -> void:
    _sequence = load(SEQUENCE_PATH) as SignalSequence
    _volume = db_to_linear(sfx_player.volume_db) if sfx_player.volume_db > -79.0 else 0.0
    _build_nodes()
    _apply_theme_colors()
    _reset_all()
    wrong_timer.timeout.connect(_on_wrong_timeout)
    restart_button.pressed.connect(restart)
    for node in nodes_box.get_children():
        node.pressed.connect(_on_node_pressed.bind(node.get_index()))

func _build_nodes() -> void:
    for child in nodes_box.get_children():
        child.queue_free()
    if _sequence == null:
        return
    var count := _sequence.node_names.size()
    for i in count:
        var b := Button.new()
        b.name = "NodeButton%d" % i
        b.text = _sequence.node_names[i] if i < _sequence.node_names.size() else "?"
        b.custom_minimum_size = Vector2(0, 84)
        b.focus_mode = Control.FOCUS_ALL
        b.focus_neighbor_left = b.get_path_to(nodes_box.get_child((i + count - 1) % count))
        b.focus_neighbor_right = b.get_path_to(nodes_box.get_child((i + 1) % count))
        nodes_box.add_child(b)

func _apply_theme_colors() -> void:
    var theme := Theme.new()
    theme.default_font_size = 24
    theme.set_color("font_color", "Label", Color(0.85, 0.9, 1.0))
    theme.set_color("font_color", "Button", Color(0.92, 0.95, 1.0))
    theme.set_color("font_hover_color", "Button", Color(1, 1, 1))
    theme.set_color("font_pressed_color", "Button", Color(1, 1, 1))
    theme.set_color("font_focus_color", "Button", Color(1, 1, 1))
    theme.set_color("font_disabled_color", "Button", Color(0.45, 0.5, 0.6))
    theme.set_constant("outline_size", "Button", 4)
    theme.set_color("font_outline_color", "Button", Color(0.02, 0.04, 0.08, 0.9))
    theme = theme
    # Use project theme if one exists; otherwise this procedural theme.
    if theme == null:
        theme = Theme.new()
    theme = theme
    if theme != null:
        theme = theme
    # Assign the same theme to all controls.
    theme = theme
    if theme != null:
        self.theme = theme

func _node_style(b: Button, color: Color, locked: bool) -> void:
    var sb := StyleBoxFlat.new()
    sb.bg_color = color.darkened(0.45) if locked else color.darkened(0.15)
    sb.border_color = color.lightened(0.25) if not locked else Color(0.2, 0.22, 0.3)
    sb.set_border_width_all(3)
    sb.set_corner_radius_all(14)
    sb.content_margin_left = 18.0
    sb.content_margin_right = 18.0
    sb.content_margin_top = 12.0
    sb.content_margin_bottom = 12.0
    b.add_theme_stylebox_override("normal", sb)
    var hover := StyleBoxFlat.new()
    hover.bg_color = color.darkened(0.05)
    hover.border_color = color.lightened(0.4)
    hover.set_border_width_all(3)
    hover.set_corner_radius_all(14)
    hover.content_margin_left = 18.0
    hover.content_margin_right = 18.0
    hover.content_margin_top = 12.0
    hover.content_margin_bottom = 12.0
    b.add_theme_stylebox_override("hover", hover)
    b.add_theme_stylebox_override("pressed", hover)
    var focus_sb := StyleBoxFlat.new()
    focus_sb.bg_color = Color(0, 0, 0, 0)
    focus_sb.border_color = Color(1, 1, 1, 0.95)
    focus_sb.set_border_width_all(4)
    focus_sb.set_corner_radius_all(14)
    focus_sb.set_expand_margin_all(4.0)
    b.add_theme_stylebox_override("focus", focus_sb)

func _reset_all() -> void:
    _progress = 0
    _busy = false
    _completed = false
    win_panel.visible = false
    wrong_timer.stop()
    if _sequence != null and _sequence.node_names.size() == 3:
        hint.text = _sequence.hint_text + "  Order: " + _sequence.display_order() + "."
    else:
        hint.text = "Sequence data missing."
    status.text = "Ready."
    for i in nodes_box.get_child_count():
        var b := nodes_box.get_child(i) as Button
        if b == null:
            continue
        var color: Color = _sequence.node_colors[i] if i < _sequence.node_colors.size() else Color.WHITE
        _node_style(b, color, false)
        b.disabled = false
        b.modulate = Color.WHITE

func _expected() -> int:
    return _sequence.sequence[_progress] if _sequence != null and _progress < _sequence.sequence.size() else -1

func _on_node_pressed(index: int) -> void:
    if _busy or _completed or _sequence == null:
        return
    var expected := _expected()
    if expected < 0:
        return
    var b := nodes_box.get_child(index) as Button
    if index == expected:
        _progress += 1
        status.text = "Correct! Step %d of %d." % [_progress, _sequence.sequence.size()]
        _play_sfx(0)
        _pulse(b, _sequence.node_colors[index], false)
        b.modulate = Color(1, 1.15, 1.15)
        if _progress >= _sequence.sequence.size():
            _win()
    else:
        _busy = true
        status.text = _sequence.wrong_text
        _play_sfx(1)
        _pulse(b, Color(1, 0.2, 0.25), true)
        _shake()
        wrong_timer.start()

func _on_wrong_timeout() -> void:
    _busy = false
    _reset_all()

func _win() -> void:
    _completed = true
    _busy = false
    wrong_timer.stop()
    _play_sfx(2)
    status.text = _sequence.win_text
    win_panel.visible = true
    restart_button.grab_focus()

func restart() -> void:
    _reset_all()
    nodes_box.get_child(0).grab_focus() if nodes_box.get_child_count() > 0 else null
    _play_sfx(1)

func _pulse(target: Button, color: Color, wrong: bool) -> void:
    var tw := create_tween()
    tw.set_trans(Tween.TRANS_SINE).set_ease(Tween.EASE_OUT)
    tw.tween_property(target, "scale", Vector2(1.12, 1.12), 0.1)
    tw.tween_property(target, "scale", Vector2(1.0, 1.0), 0.18)
    if wrong:
        var t2 := create_tween()
        t2.tween_property(target, "modulate", Color(1, 0.45, 0.45), 0.08)
        t2.tween_property(target, "modulate", Color.WHITE, 0.35)
    else:
        var t2 := create_tween()
        t2.tween_property(target, "modulate", color.lightened(0.25), 0.12)
        t2.tween_property(target, "modulate", Color(1, 1.15, 1.15), 0.25)

func _shake() -> void:
    var tw := create_tween()
    var orig := position
    for i in 4:
        tw.tween_property(self, "position", orig + Vector2((i % 2 * 2 - 1) * 6.0, 0), 0.05)
    tw.tween_property(self, "position", orig, 0.05)

func _play_sfx(kind: int) -> void:
    if sfx_player == null:
        return
    var a := AudioStreamGenerator.new()
    a.mix_rate = 22050.0
    a.buffer_length = 0.3
    sfx_player.stream = a
    if kind == 0:
        # Correct: rising tone.
        _tone(sfx_player, a, 0.14, 660.0)
    elif kind == 1:
        # Wrong: low buzz.
        _tone(sfx_player, a, 0.3, 140.0)
    else:
        # Win: rising arpeggio feel.
        _tone(sfx_player, a, 0.35, 880.0)
    sfx_player.play()

func _tone(p: AudioStreamPlayer, gen: AudioStreamGenerator, dur: float, freq: float) -> void:
    var play := p.get_stream_playback() as AudioStreamGeneratorPlayback
    if play == null:
        return
    var frames := int(dur * 22050.0)
    var phase := 0.0
    for i in frames:
        var t := float(i) / 22050.0
        var envelope := 1.0 - t / dur
        if kind_freq(gen, freq) <= 0.0:
            pass
        var sample := sin(phase * TAU) * envelope * 0.6 * _volume
        play.push_frame(Vector2(sample, sample))
        phase += freq / 22050.0

func kind_freq(gen: AudioStreamGenerator, freq: float) -> float:
    return freq
`;

const r = await tools["mcp__godot-ai__script_create"]({
  path: "res://validation_games/signal_circuit/signal_circuit.gd",
  content: mainScript,
});
console.log("CREATE MAIN SCRIPT:", JSON.stringify(r.structuredContent, null, 2));

// Attach
const a = await tools["mcp__godot-ai__script_attach"]({
  path: "/SignalCircuit",
  script_path: "res://validation_games/signal_circuit/signal_circuit.gd",
});
console.log("ATTACH:", JSON.stringify(a.structuredContent, null, 2));
return "script created+attached";", "description": "Create main game script and attach to root"}

